public class Q29_Shared_Counter_With_Synchronization { static int counter=0; static synchronized void increment(){counter++;} public static void main(String[] args) throws InterruptedException { Runnable task=()->{for(int i=0;i<100000;i++)increment();}; Thread a=new Thread(task),b=new Thread(task);a.start();b.start();a.join();b.join();System.out.println("Expected and actual = "+counter); } }
